        assertNull(before.get("rate").asText(null));
        assertNull(before.get("trialLoss").asText(null));
        // 不传日期：仅返回余额类实际值
        JsonNode bare = getOk("/api/allocations/" + a + "/settlement-diagnostic");
        assertEquals("3.5", bare.get("remainingSettleable").asText());
        assertNull(bare.get("deliveryDate").asText(null));
        // 诊断不改变任何状态
        assertEquals("3.5", allocationView(windowId, a).get("heldAmount").asText());
        assertEquals(0, getOk("/api/windows/" + windowId + "/settlements").get("settlements").size());
        // 申请不存在 -> 404
        mvc.perform(get("/api/allocations/missing-" + run + "/settlement-diagnostic"))
                .andExpect(status().isNotFound());
    }

    @Test
    void invalidRateParamsReturn400() throws Exception {
        postExpect("/api/evaporation-rates", rateBody(key("rc"), channel(), "2026-11-10", "0.2001"),
                400, "INVALID_ARGUMENT");
        postExpect("/api/evaporation-rates", rateBody(key("rc"), channel(), "2026-11-10", "-0.01"),
                400, "INVALID_ARGUMENT");
        postExpect("/api/evaporation-rates", rateBody(key("rc"), channel(), "2026-11-10", "0.12345"),
                400, "INVALID_ARGUMENT");
        postExpect("/api/evaporation-rates", rateBody(key("rc"), channel(), "bad-date", "0.1"),
                400, "INVALID_ARGUMENT");
        postExpect("/api/evaporation-rates", rateBody(key("rc"), channel(), "2026-11-10", "abc"),
                400, "INVALID_ARGUMENT");
    }

    private Map<String, Object> rateBody(String commandKey, String channelId, String date, String rate) {
        Map<String, Object> body = new HashMap<>();
        body.put("commandKey", commandKey);
        body.put("channelId", channelId);
        body.put("rateDate", date);
        body.put("rate", rate);
        lastCommand = commandKey;
        previousCommand = commandKey;
        return body;
    }

    private List<JsonNode> jsonNodes(JsonNode array) {
        List<JsonNode> list = new ArrayList<>();
        array.forEach(list::add);
        return list;
    }
